use genewars_assets::ConqMissionSource;
use genewars_runtime::{actor_world::ActorWorld,actor_pool::ActorHandleBindings,blueprint::BlueprintRng,player_state::PlayerState,terrain_job_pool::TerrainJobPool,construction_maintenance::TerrainEnvironment};
use std::{fs,path::Path,io::Write};
fn snapshot(w:&ActorWorld,j:&TerrainJobPool)->Vec<u8>{let mut b=w.backing_bytes().to_vec();for r in w.actors().records(){b.extend(r);}for r in w.creatures().unwrap().records(){b.extend(r);}for r in w.buildings().unwrap().records(){b.extend(r);}for p in 0..4{b.extend(w.player(p).unwrap().bytes());}let r=w.rng();b.extend(r.seed.to_le_bytes());b.push(r.ring);b.extend(r.draw_count.to_le_bytes());for r in j.records(){b.extend(r);}b.push(j.count());b}
fn main(){let a:Vec<_>=std::env::args().collect();let work=Path::new(&a[1]);let border=fs::read(work.join("border.bin")).unwrap();let mut ledger=fs::File::create(work.join("results.tsv")).unwrap();
for line in fs::read_to_string(work.join("cases.txt")).unwrap().lines(){let d=work.join(line);let mission=fs::read(d.join("mission.bin")).unwrap();let source=ConqMissionSource::parse(&mission).unwrap();let raw=fs::read(d.join("pool.bin")).unwrap();let count=raw[4400];let records=std::array::from_fn(|i|raw[i*176..(i+1)*176].try_into().unwrap());let mut jobs=TerrainJobPool::admit(records,count).unwrap();let players=std::array::from_fn(|p|PlayerState::fresh_campaign(p as u8,[20736,13568],b"fixture\0").unwrap());let mut world=ActorWorld::from_parts(&source,&[[0;200];20],[ActorHandleBindings::empty();20],players,BlueprintRng{seed:5428,ring:31,draw_count:u32::MAX}).unwrap();world.admit_creatures(&[[0;124];300]).unwrap();world.admit_buildings(&[[0xA5;67];256],[None;256]).unwrap();fs::write(d.join("before.bin"),snapshot(&world,&jobs)).unwrap();let saved=world.clone();let saved_jobs=jobs.clone();let result=world.step_terrain_jobs(&mut jobs,TerrainEnvironment{climate_center:[0,0],raw_water_height:816,climate:106,light:[181,0,-181]},border.as_slice().try_into().unwrap());
match result{Ok(receipts)=>{let mut events=Vec::new();for r in receipts{assert!(!r.terrain_objects_refresh_required);for c in r.viewport_invalidations{events.extend(c.to_le_bytes());}}fs::write(d.join("events.bin"),events).unwrap();writeln!(ledger,"{line}\tPASS").unwrap();},Err(e)=>{assert_eq!(world,saved);assert_eq!(jobs,saved_jobs);fs::write(d.join("events.bin"),[]).unwrap();writeln!(ledger,"{line}\t{e:?}").unwrap();}}
fs::write(d.join("after.bin"),snapshot(&world,&jobs)).unwrap();}}
